{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A gentle map for scent practice</title>
  <meta name="description" content="Aromatherapy sessions and bespoke blends that may support rest, clarity, and calm. Safety-forward guidance included.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-soft">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="url(#g)"/><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#EDE7F6"/><stop offset="1" stop-color="#E3F8F2"/></linearGradient></defs></svg>
      <div>
        <h1 class="business">{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="nav">
      <a href="index.html">Welcome</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">About</a>
      <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html" aria-label="contact">Connect</a>
    </nav>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero reveal" id="hero">
      <div class="hero-content">
        <h2>Quiet rituals shaped for your pace</h2>
        <p class="lead">Tailored aromatic sessions and curated blends that may support gentle focus, ease, and a steadying rhythm.</p>
        <div class="hero-actions">
          <a href="book.html" class="btn primary">Start a Session</a>
          <a href="#planner" class="btn ghost">Try the Session Planner</a>
        </div>
      </div>
      <div class="hero-decor" aria-hidden="true">
        <svg viewBox="0 0 200 200" class="orn" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="lg" x1="0" x2="1"><stop offset="0" stop-color="#F1F7F3"/><stop offset="1" stop-color="#FFF7F0"/></linearGradient></defs><circle cx="100" cy="100" r="80" fill="url(#lg)"/></svg>
      </div>
    </section>

    <!-- FRAMEWORK (moved up) -->
    <section class="framework reveal" id="framework">
      <div class="container">
        <h3>How we shape practice</h3>
        <p class="muted">A simple three-step approach to build approachable scent practices that may support daily balance.</p>
        <div class="steps">
          <div class="step">
            <h4>Listen</h4>
            <p>Short intake to notice context — sleep, mood, pets, pregnancy notes — and safety checks.</p>
          </div>
          <div class="step">
            <h4>Design</h4>
            <p>Personalized scent choices and dilution guidance that may support the aim you named.</p>
          </div>
          <div class="step">
            <h4>Practice</h4>
            <p>Simple rituals and timing suggestions to fold small aromatic moments into your day.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story reveal" id="story">
      <div class="container narrow">
        <h3>Why scent, softly</h3>
        <p>Essential oils are companions for intention. Sessions focus on practical safety, dilution, and a paced practice rather than bold cures. Expect mindful pairing, patch-test guidance, and attention to pets and pregnancy considerations.</p>
        <p class="attribution">Served in person in {{CITY}}, {{STATE}} and online.</p>
      </div>
    </section>

    <!-- OFFERS -->
    <section class="offers reveal" id="offers">
      <div class="container">
        <h3>Programs & Blends</h3>
        <div class="cards">
          <article class="card">
            <h4>Solo Session</h4>
            <p class="price">45–60 min • $95</p>
            <p>One-on-one intake and a bespoke blend with dilution notes; take-home summary included.</p>
            <a class="btn" href="book.html">Reserve a Solo Session</a>
          </article>
          <article class="card">
            <h4>Guided Rhythm (3)</h4>
            <p class="price">Three sessions • $260</p>
            <p>A short series for embedding a new scent habit with incremental adjustments.</p>
            <a class="btn" href="pricing.html">View Plans</a>
          </article>
          <article class="card">
            <h4>Custom Blend</h4>
            <p class="price">From $35</p>
            <p>Small-batch blends with safe dilution ranges and usage notes. Shipping available.</p>
            <a class="btn" href="blends.html">See Blends</a>
          </article>
        </div>
      </div>
    </section>

    <!-- PRICING SUMMARY -->
    <section class="pricing reveal" id="pricing">
      <div class="container narrow">
        <h3>Transparent pricing</h3>
        <p>Sessions framed as light commitments — consistent, modest pricing to encourage practice without pressure.</p>
        <ul class="price-list">
          <li>Solo Session — $95</li>
          <li>Guided Rhythm (3) — $260</li>
          <li>Blend Starter Kit — $45</li>
        </ul>
        <a href="pricing.html" class="btn">See full details</a>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials reveal" id="testimonials">
      <div class="container">
        <h3>Notes from people who tried it</h3>
        <blockquote>"Gentle suggestions and clear safety notes — I use the blend daily. It feels like a small anchor." — A.</blockquote>
        <blockquote>"Practical and calm: a planner that helped me keep a short ritual for sleep." — R.</blockquote>
      </div>
    </section>

    <!-- CTA + Session Planner widget -->
    <section class="cta reveal" id="cta">
      <div class="container">
        <h3>Plan a Gentle Session</h3>
        <p>Build a short, personalized aromatic plan and export a plain-text summary you can save or share.</p>
        <div id="planner" class="planner" aria-live="polite">
          <form id="plannerForm">
            <label>Primary goal
              <select id="goal">
                <option value="calm">Calm & unwind</option>
                <option value="focus">Focus & clarity</option>
                <option value="sleep">Support sleep</option>
                <option value="mood">Gentle mood lift</option>
              </select>
            </label>
            <label>Session length
              <select id="length">
                <option value="5">5 minutes</option>
                <option value="10">10 minutes</option>
                <option value="15">15 minutes</option>
              </select>
            </label>
            <label>Days per week
              <input id="frequency" type="number" min="1" max="7" value="3">
            </label>
            <label>Preferences or notes
              <input id="notes" type="text" placeholder="e.g., no citrus, pets at home, pregnancy">
            </label>
            <div class="planner-actions">
              <button type="button" class="btn primary" id="buildBtn">Build plan</button>
              <button type="button" class="btn" id="copyBtn">Copy summary</button>
              <a class="btn ghost" id="downloadBtn">Download</a>
            </div>
          </form>
          <pre id="summary" class="summary" tabindex="0" aria-label="Session summary">Your session summary will appear here.</pre>
          <div class="safety-note">
            <strong>Safety:</strong> Always patch-test new blends, follow dilution guidance, and consult a qualified provider for pregnancy or major health concerns. Keep oils away from pets' faces and open water bowls.
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <p>Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <p>&copy; <span id="yr"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
