{"path":"assets/css/styles.css","content":"/* Core styles — minimal, poetic, accessible */
:root{
  --bg:#fffdf9; --muted:#6b6b6b; --brand:#6aa6a1; --accent:#e6d7f0; --card:#ffffff; --shadow:0 8px 20px rgba(20,20,20,0.06);
  --radius:12px; --max-width:1100px; --gutter:24px; font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:#1b1b1b;line-height:1.45}
.container{max-width:var(--max-width);margin:0 auto;padding:48px var(--gutter)}
.narrow{max-width:800px}
.site-header{display:flex;justify-content:space-between;align-items:center;padding:18px var(--gutter);background:linear-gradient(180deg,rgba(255,255,255,0.9),transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:10}
.brand{display:flex;gap:12px;align-items:center}
.logo{border-radius:8px}
.business{font-size:1rem;margin:0}
.tag{margin:0;font-size:0.85rem;color:var(--muted)}
.nav{display:flex;gap:12px;align-items:center}
.nav a{color:inherit;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:var(--brand);color:white}
.hero{display:grid;grid-template-columns:1fr 300px;gap:24px;padding:64px var(--gutter);align-items:center}
.hero-content h2{font-size:clamp(1.25rem,3vw,2rem);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;background:transparent;border:1px solid rgba(0,0,0,0.06);text-decoration:none;color:inherit}
.btn.primary{background:var(--brand);color:white;border:none}
.btn.ghost{background:transparent}
.hero-decor{opacity:0.95}
.framework,.story,.offers,.pricing,.testimonials,.cta{padding:48px var(--gutter);background-image:url('/assets/img/pattern.svg');background-repeat:repeat;}
.steps{display:flex;gap:18px;margin-top:18px}
.step{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow);flex:1}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.price{font-weight:700}
.price-list{list-style:none;padding:0;margin:12px 0}
.testimonials blockquote{background:linear-gradient(90deg,#fff,#f9f9fb);padding:16px;border-left:4px solid var(--brand);border-radius:8px}
.site-footer{padding:28px var(--gutter);color:var(--muted)}
.planner{background:#fff;padding:18px;border-radius:12px;box-shadow:var(--shadow);max-width:900px;margin-top:18px}
.planner form{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}
.planner label{display:block;font-size:0.9rem;color:var(--muted)}
.planner input,.planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #eee}
.planner-actions{grid-column:1/-1;display:flex;gap:8px;margin-top:6px}
.summary{background:#f7f7f8;padding:12px;border-radius:8px;white-space:pre-wrap;min-height:120px;margin-top:12px}
.safety-note{font-size:0.85rem;color:var(--muted);margin-top:8px}
/* Reveal animation */
.reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease,transform 420ms ease}
.reveal.revealed{opacity:1;transform:none}
/* Reduced motion */
@media (prefers-reduced-motion:reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* Responsive tweaks */
@media (max-width:800px){
  .hero{grid-template-columns:1fr;}
  .nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  'use strict';
  // utility
  function $(sel, ctx){return (ctx||document).querySelector(sel)}
  function $all(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // set year
  var yr = new Date().getFullYear(); var yrEl = $('#yr'); if(yrEl) yrEl.textContent = yr;

  // Scroll reveal with prefers-reduced-motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var revealEls = $all('.reveal');
  if(prefersReduced){ revealEls.forEach(function(el){ el.classList.add('revealed'); }); }
  else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('revealed'); io.unobserve(e.target); } });
    },{rootMargin:'0px 0px -10% 0px',threshold:0.08});
    revealEls.forEach(function(el){ io.observe(el); });
  } else { revealEls.forEach(function(el){ el.classList.add('revealed'); }); }

  // Session Planner
  var form = $('#plannerForm');
  var buildBtn = $('#buildBtn');
  var copyBtn = $('#copyBtn');
  var downloadBtn = $('#downloadBtn');
  var summaryEl = $('#summary');

  function buildSummary(){
    var goal = $('#goal').value;
    var length = $('#length').value;
    var freq = $('#frequency').value;
    var notes = $('#notes').value.trim();
    var goalText = {
      calm: 'Calm & unwind',
      focus: 'Focus & clarity',
      sleep: 'Support sleep',
      mood: 'Gentle mood lift'
    }[goal]||goal;
    var dilution = (length <= 5) ? '1-2% for short inhalation' : '2-3% for brief topical use (if appropriate)';
    var plan = [];
    plan.push('Session plan — created on ' + new Date().toLocaleDateString());
    plan.push('Primary aim: ' + goalText);
    plan.push('Length: ' + length + ' minutes');
    plan.push('Frequency: ' + freq + ' days per week');
    if(notes) plan.push('Notes: ' + notes);
    plan.push('Suggested approach:');
    plan.push('- Begin with 1 minute mindful breathing with chosen aroma.');
    plan.push('- Use 2–3 short inhales across the session, rest between steps.');
    plan.push('- Blend guidance: ' + dilution + '. Patch-test suggested before topical use.');
    plan.push('Safety reminders: keep oils away from eyes and pets\' faces; consult a provider for pregnancy or major medical concerns.');
    plan.push('\nPrepared by: ' + '{{BUSINESS_NAME}}');
    return plan.join('\n');
  }

  function showSummary(text){ summaryEl.textContent = text; summaryEl.focus(); }

  if(buildBtn){ buildBtn.addEventListener('click', function(e){ e.preventDefault(); var t = buildSummary(); showSummary(t); }); }

  if(copyBtn){ copyBtn.addEventListener('click', function(){ var text = summaryEl.textContent || ''; if(!text) return; navigator.clipboard && navigator.clipboard.writeText(text).then(function(){ copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy summary',1400); }).catch(function(){ fallbackCopy(text); }); }); }

  function fallbackCopy(text){ var ta = document.createElement('textarea'); ta.value=text; ta.style.position='fixed'; ta.style.left='-9999px'; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Copied'); }catch(e){ alert('Copy failed'); } document.body.removeChild(ta); }

  if(downloadBtn){ downloadBtn.addEventListener('click', function(){ var text = summaryEl.textContent || ''; if(!text) return; var blob = new Blob([text],{type:'text/plain'}); var url = URL.createObjectURL(blob); downloadBtn.setAttribute('href',url); downloadBtn.setAttribute('download','session-plan.txt'); setTimeout(function(){ URL.revokeObjectURL(url); }, 4000); }); }

  // simple keyboard accessibility for summary (allow select all)
  if(summaryEl){ summaryEl.addEventListener('keydown', function(e){ if((e.ctrlKey||e.metaKey) && e.key==='a'){ e.stopPropagation(); } }); }
})();"} 
